class AuditChain(private val sink: Sink, key: ByteArray) {     // one instance per process
    private val log = KotlinLogging.logger("audit")
    private val mac = Mac.getInstance("HmacSHA256").apply { init(SecretKeySpec(key, "HmacSHA256")) }
    private var prev = ByteArray(0); private var seq = 0L
    @Synchronized fun append(event: AuditEvent) {
        val body = canonicalise(event)                        // explicit redacted form
        mac.update(prev); mac.update(seq.toBigEndian()); mac.update(body)
        prev = mac.doFinal()
        sink.append(seq, prev, body)                          // append-only, fsync per policy
        log.info { "audit seq=$seq" }; seq++
    }
}
